class Solution {
    static int solution(int[] deck) {
        int n = deck.length, pos = -1;
        for (int i = 0; i < n; i++) if (deck[i] == 1) { pos = i; break; }
        if (pos < 0) return -1;
        for (int i = 0; i < n; i++)
            if (deck[(pos + i) % n] != i + 1) return -1;
        return pos;
    }
}

